<?php
namespace App\Services;
final class PngBadgeService {
    private const FONT=[
      'A'=>['01110','10001','10001','11111','10001','10001','10001'],'B'=>['11110','10001','10001','11110','10001','10001','11110'],'C'=>['01111','10000','10000','10000','10000','10000','01111'],'D'=>['11110','10001','10001','10001','10001','10001','11110'],'E'=>['11111','10000','10000','11110','10000','10000','11111'],'F'=>['11111','10000','10000','11110','10000','10000','10000'],'G'=>['01111','10000','10000','10111','10001','10001','01111'],'H'=>['10001','10001','10001','11111','10001','10001','10001'],'I'=>['11111','00100','00100','00100','00100','00100','11111'],'J'=>['00111','00010','00010','00010','10010','10010','01100'],'K'=>['10001','10010','10100','11000','10100','10010','10001'],'L'=>['10000','10000','10000','10000','10000','10000','11111'],'M'=>['10001','11011','10101','10101','10001','10001','10001'],'N'=>['10001','11001','10101','10011','10001','10001','10001'],'O'=>['01110','10001','10001','10001','10001','10001','01110'],'P'=>['11110','10001','10001','11110','10000','10000','10000'],'Q'=>['01110','10001','10001','10001','10101','10010','01101'],'R'=>['11110','10001','10001','11110','10100','10010','10001'],'S'=>['01111','10000','10000','01110','00001','00001','11110'],'T'=>['11111','00100','00100','00100','00100','00100','00100'],'U'=>['10001','10001','10001','10001','10001','10001','01110'],'V'=>['10001','10001','10001','10001','10001','01010','00100'],'W'=>['10001','10001','10001','10101','10101','10101','01010'],'X'=>['10001','10001','01010','00100','01010','10001','10001'],'Y'=>['10001','10001','01010','00100','00100','00100','00100'],'Z'=>['11111','00001','00010','00100','01000','10000','11111'],
      '0'=>['01110','10001','10011','10101','11001','10001','01110'],'1'=>['00100','01100','00100','00100','00100','00100','01110'],'2'=>['01110','10001','00001','00010','00100','01000','11111'],'3'=>['11110','00001','00001','01110','00001','00001','11110'],'4'=>['00010','00110','01010','10010','11111','00010','00010'],'5'=>['11111','10000','10000','11110','00001','00001','11110'],'6'=>['01110','10000','10000','11110','10001','10001','01110'],'7'=>['11111','00001','00010','00100','01000','01000','01000'],'8'=>['01110','10001','10001','01110','10001','10001','01110'],'9'=>['01110','10001','10001','01111','00001','00001','01110'],'/'=>['00001','00010','00100','01000','10000','00000','00000'],' '=>['00000','00000','00000','00000','00000','00000','00000']
    ];
    public static function render(int $ready,int $total): string {
        $w=300;$h=56;$img=array_fill(0,$h,str_repeat("\xFF\xFF\xFF",$w));
        $set=function(int $x,int $y,array $rgb)use(&$img,$w,$h){if($x<0||$y<0||$x>=$w||$y>=$h)return;$row=$img[$y];$off=$x*3;$row=substr_replace($row,chr($rgb[0]).chr($rgb[1]).chr($rgb[2]),$off,3);$img[$y]=$row;};
        for($x=0;$x<$w;$x++){ $set($x,0,[230,222,216]);$set($x,$h-1,[230,222,216]); } for($y=0;$y<$h;$y++){ $set(0,$y,[230,222,216]);$set($w-1,$y,[230,222,216]); }
        $draw=function(string $text,int $x,int $y,int $scale,array $color)use($set){foreach(str_split(strtoupper($text)) as $ch){$g=self::FONT[$ch]??self::FONT[' '];foreach($g as $ry=>$bits)foreach(str_split($bits) as $rx=>$bit)if($bit==='1')for($yy=0;$yy<$scale;$yy++)for($xx=0;$xx<$scale;$xx++)$set($x+$rx*$scale+$xx,$y+$ry*$scale+$yy,$color);$x+=6*$scale;} };
        $draw('RUNS ON SIUGOALS',18,18,2,[32,30,33]);$draw($ready.'/'.$total,238,18,2,[53,180,158]);
        $raw='';foreach($img as $row)$raw.="\x00".$row;
        $chunk=function(string $type,string $data){return pack('N',strlen($data)).$type.$data.pack('N',crc32($type.$data));};
        return "\x89PNG\r\n\x1a\n".$chunk('IHDR',pack('NNCCCCC',$w,$h,8,2,0,0,0)).$chunk('IDAT',gzcompress($raw,9)).$chunk('IEND','');
    }
}
